@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,700&family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&display=swap');

:root {
  /* Brand Colors in OKLCH */
  --brand-primary: oklch(53.30% 0.131 155.41); /* #00824A */
  --brand-dark: oklch(37.01% 0.046 141.36);    /* #32462F */
  --brand-cream: oklch(87.22% 0.072 72.11);    /* #F3CEA1 */
  --brand-coffee: oklch(30% 0.05 45);          /* Rich brown */

  /* UI Colors */
  --bg-surface: oklch(98% 0.02 72);
  --bg-white: #FFFFFF;
  --text-primary: oklch(20% 0.02 141);
  --text-secondary: oklch(40% 0.02 141);
  --border-light: oklch(90% 0.02 72);
  --accent-orange: oklch(65% 0.18 45);

  /* Typography */
  --font-heading: 'Fraunces', serif;
  --font-body: 'DM Sans', sans-serif;

  /* Spacing */
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --space-2xl: 6rem;

  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.05);
  --shadow-md: 0 8px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 16px 40px rgba(0,0,0,0.12);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  color: var(--text-primary);
  background-color: var(--bg-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  line-height: 1.2;
  color: var(--brand-dark);
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* Utilities */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-md);
}

.text-center { text-align: center; }
.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.8rem 1.5rem;
  border-radius: var(--radius-full);
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  text-align: center;
}

.btn-primary {
  background-color: var(--brand-primary);
  color: white;
}
.btn-primary:hover {
  background-color: var(--brand-dark);
  transform: translateY(-2px);
}

.btn-secondary {
  background-color: transparent;
  color: var(--brand-primary);
  border: 1px solid var(--brand-primary);
}
.btn-secondary:hover {
  background-color: var(--brand-primary);
  color: white;
}

/* Header */
.global-header {
  background-color: var(--bg-white);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--brand-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background-color: var(--brand-primary);
  border-radius: 50%;
  display: inline-block;
}

.nav-links {
  display: flex;
  gap: var(--space-lg);
  font-weight: 500;
}

.nav-links a:hover {
  color: var(--brand-primary);
}

.nav-actions {
  display: flex;
  gap: var(--space-sm);
  align-items: center;
}

/* Hero Section */
.hero {
  background-color: var(--brand-cream);
  padding: var(--space-2xl) 0;
  display: flex;
  align-items: center;
  overflow: hidden;
  position: relative;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
}

.hero-content h1 {
  font-size: 3.5rem;
  margin-bottom: var(--space-md);
}

.hero-image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  aspect-ratio: 4/3;
  background-color: var(--brand-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--brand-cream);
  font-family: var(--font-heading);
  font-size: 1.5rem;
}

/* Sections */
.section-padding {
  padding: var(--space-xl) 0;
}

.bento-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-md);
}

.bento-item {
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s ease;
}

.bento-item:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
}

.bento-image {
  height: 200px;
  background: var(--brand-cream);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-md);
}

.promo-banner {
  background-color: var(--brand-dark);
  color: white;
  text-align: center;
  padding: var(--space-xl) var(--space-md);
  border-radius: var(--radius-lg);
  margin: var(--space-xl) 0;
}
.promo-banner h2 {
  color: white;
}

/* Footer */
.global-footer {
  background-color: var(--brand-coffee);
  color: var(--bg-surface);
  padding: var(--space-2xl) 0 var(--space-lg);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-xl);
  margin-bottom: var(--space-xl);
}

.footer-col h3 {
  color: var(--brand-cream);
  font-family: var(--font-body);
  font-size: 1rem;
  margin-bottom: var(--space-md);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: var(--space-sm);
}

.footer-col a {
  opacity: 0.8;
  transition: opacity 0.2s;
}

.footer-col a:hover {
  opacity: 1;
  text-decoration: underline;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--space-lg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  opacity: 0.7;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: var(--space-md);
  left: var(--space-md);
  right: var(--space-md);
  background: var(--bg-white);
  padding: var(--space-md);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  z-index: 1000;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-md);
  border: 1px solid var(--border-light);
}

.cookie-content h4 {
  margin-bottom: 0.25rem;
}
.cookie-content p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
}

/* Responsive */
@media (max-width: 768px) {
  .hero-grid {
    grid-template-columns: 1fr;
  }
  .nav-links {
    display: none; /* simple mobile behavior for now */
  }
  .footer-col h3 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-col h3::after {
    content: '+';
    font-size: 1.2rem;
  }
  .footer-col.expanded h3::after {
    content: '-';
  }
  .footer-col ul {
    display: none;
  }
  .footer-col.expanded ul {
    display: block;
    margin-top: var(--space-sm);
  }
  .cookie-banner {
    flex-direction: column;
    align-items: stretch;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Cookie Banner
  const cookieBanner = document.getElementById('cookie-banner');
  const cookieAgreeBtn = document.getElementById('cookie-agree');

  if (cookieBanner && cookieAgreeBtn) {
    cookieAgreeBtn.addEventListener('click', () => {
      cookieBanner.style.display = 'none';
    });
  }

  // Footer Accordion (Mobile)
  const footerHeadings = document.querySelectorAll('.footer-col h3');
  footerHeadings.forEach(heading => {
    heading.addEventListener('click', () => {
      if (window.innerWidth <= 768) {
        heading.parentElement.classList.toggle('expanded');
      }
    });
  });

  // Rewards Tier Tabs
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');

  if (tabBtns.length > 0) {
    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Remove active class from all
        tabBtns.forEach(b => b.classList.remove('active'));
        tabContents.forEach(c => c.classList.remove('active'));

        // Add active to clicked
        btn.classList.add('active');
        const targetId = btn.getAttribute('data-target');
        document.getElementById(targetId).classList.add('active');
      });
    });
  }

  // Carousel Next/Prev logic
  const carousels = document.querySelectorAll('.carousel-container');
  carousels.forEach(carousel => {
    const track = carousel.querySelector('.carousel-track');
    const prevBtn = carousel.querySelector('.carousel-prev');
    const nextBtn = carousel.querySelector('.carousel-next');

    if (track && prevBtn && nextBtn) {
      prevBtn.addEventListener('click', () => {
        track.scrollBy({ left: -300, behavior: 'smooth' });
      });
      nextBtn.addEventListener('click', () => {
        track.scrollBy({ left: 300, behavior: 'smooth' });
      });
    }
  });

  // Store Locator Filter Toggle
  const filterBtn = document.getElementById('filter-btn');
  const filterPanel = document.getElementById('filter-panel');
  if (filterBtn && filterPanel) {
    filterBtn.addEventListener('click', () => {
      filterPanel.classList.toggle('open');
    });
  }

  // Store Locator Order Type Toggle
  const typeBtns = document.querySelectorAll('.type-btn');
  if (typeBtns.length > 0) {
    typeBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        typeBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        // A real app would filter results here
      });
    });
  }

  // Store Locator Search
  const searchInput = document.getElementById('store-search');
  const searchSuggestions = document.getElementById('search-suggestions');
  if (searchInput && searchSuggestions) {
    searchInput.addEventListener('input', (e) => {
      if (e.target.value.length > 2) {
        searchSuggestions.style.display = 'block';
      } else {
        searchSuggestions.style.display = 'none';
      }
    });
  }
});
